<template><div class="bulk-bar"><span>{{ selection.length }} selected</span><el-button :disabled="!selection.length" @click="visible=true">Set Labels / Save Drafts</el-button><el-button type="success" :disabled="!selection.length || selection.some(r=>!r.hasDraft) || busy" @click="publish">Publish Selected Drafts</el-button><span class="muted">Publish includes all saved draft edits. Review individual records first.</span><el-dialog title="Bulk Content Labels" :visible.sync="visible" width="660px" :close-on-click-modal="false"><el-alert title="Only commercial label, redemption price and validity are changed. Other fields in each existing draft are preserved." type="info" :closable="false"/><p>{{ selection.map(r=>r.name).join(', ') }}</p><el-form label-width="145px" :disabled="busy"><el-form-item label="Commercial Label"><el-radio-group v-model="tier"><el-radio-button label="free">Free</el-radio-button><el-radio-button label="premium">Premium</el-radio-button><el-radio-button label="featured">Featured</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="tier==='featured'" label="Redemption Credits"><admin-number v-model="credits" :min="1" :max="1000000" :precision="0"/></el-form-item><el-form-item v-if="tier==='featured'" label="Validity"><el-switch v-model="noExpiry" active-text="No expiry"/><div v-if="!noExpiry"><admin-number v-model="days" :min="1" :max="3650" :precision="0"/> days</div></el-form-item></el-form><p class="field-help">Saved drafts do not change App access. A conflict or invalid record cancels the entire batch.</p><span slot="footer"><el-button @click="visible=false">Cancel</el-button><el-button type="primary" :loading="busy" @click="save">Save {{ selection.length }} Drafts</el-button></span></el-dialog></div></template>
<script>
import {bulkContent} from '@/api/commerce'
import AdminNumber from '@/components/AdminNumber'
export default{components:{AdminNumber},props:{selection:{type:Array,required:true}},data(){return{visible:false,busy:false,tier:'free',credits:30,noExpiry:true,days:365}},methods:{items(){return this.selection.map(r=>({id:r.id,revision:r.revision}))},async save(){this.busy=true;try{await bulkContent({action:'save',items:this.items(),tier:this.tier,redemptionCredits:this.credits,redemptionValidityDays:this.noExpiry?null:this.days});this.visible=false;this.$message.success('Drafts saved. Review before publishing.');this.$emit('changed')}catch(_){}finally{this.busy=false}},async publish(){try{await this.$confirm(`Publish ALL saved draft fields on ${this.selection.length} selected records? New starts use the published labels; existing redemptions retain their validity.`, 'Publish Content Drafts',{confirmButtonText:'Publish',type:'warning'})}catch(_){return}this.busy=true;try{await bulkContent({action:'publish',items:this.items()});this.$emit('changed');this.$message.success('Selected versions published.')}catch(_){}finally{this.busy=false}}}}
</script>
